package fr.shenpulse.diamondrush;
import java.lang.reflect.*;import java.util.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.scheduler.BukkitRunnable;
public final class DiamondBridge extends DiamondRush {
 private boolean arenaReady=false;private int observedWins;
 @Override public void onEnable(){super.onEnable();getCommand("shenpulse_dr").setExecutor(this);getServer().getPluginManager().registerEvents(new Listener(){@EventHandler public void join(PlayerJoinEvent e){Bukkit.getScheduler().runTaskLater(DiamondBridge.this,()->teleport(e.getPlayer()),20L);}},this);prepareMine();observedWins=integer("totalWins");Bukkit.getScheduler().runTaskTimer(this,()->{int current=integer("totalWins");if(current!=observedWins){observedWins=current;getLogger().info("SHENPULSE_WIN_COUNTER current="+current+" source=auto-win");}},20L,20L);}
 private void teleport(Player p){if(arenaReady)p.teleport(new Location(Bukkit.getWorlds().get(0),0.5,34,0.5));}
 private void prepareMine(){arenaReady=false;World w=Bukkit.getWorlds().get(0);w.setSpawnLocation(0,34,0);w.setGameRule(GameRule.DO_MOB_SPAWNING,false);new BukkitRunnable(){int index=0;Random r=new Random(571331);public void run(){for(int n=0;n<1400&&index<41*41*44;n++,index++){int x=index%41-20,z=(index/41)%41-20,y=index/(41*41)-9;Material m=y==-9||Math.abs(x)==20||Math.abs(z)==20?Material.BEDROCK:y>=32?Material.AIR:r.nextInt(100)<12?Material.DIAMOND_ORE:r.nextInt(300)==0?Material.AMETHYST_BLOCK:Material.STONE;w.getBlockAt(x,y,z).setType(m,false);}if(index>=41*41*44){for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)w.getBlockAt(x,33,z).setType(Material.SMOOTH_STONE,false);arenaReady=true;for(Player p:Bukkit.getOnlinePlayers())teleport(p);getLogger().info("ShenPulse Diamond Rush : mine prête.");cancel();}}}.runTaskTimer(this,1L,1L);}
 private int integer(String n){try{Field f=DiamondRush.class.getDeclaredField(n);f.setAccessible(true);return f.getInt(this);}catch(Exception e){throw new IllegalStateException(e);}}
 private void integer(String n,int value){try{Field f=DiamondRush.class.getDeclaredField(n);f.setAccessible(true);f.setInt(this,value);}catch(Exception e){throw new IllegalStateException(e);}}
 private void call(String n,Class<?>[] types,Object... values){try{Method m=DiamondRush.class.getDeclaredMethod(n,types);m.setAccessible(true);m.invoke(this,values);}catch(Exception e){throw new IllegalStateException(e);}}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!command.getName().equals("shenpulse_dr"))return super.onCommand(sender,command,label,args);if(sender instanceof Player){sender.sendMessage("Commande réservée à ShenPulse.");return true;}try{if(args.length==0)throw new IllegalArgumentException();String action=args[0];int value=args.length>1?Math.max(1,Math.min(3000,Integer.parseInt(args[1]))):1;String viewer=args.length>2?String.join(" ",Arrays.copyOfRange(args,2,args.length)):"Viewer";
 if(action.equals("regenerate")){integer("totalDiamonds",0);prepareMine();return true;}if(action.equals("sync")){integer("totalWins",Integer.parseInt(args[1]));observedWins=integer("totalWins");if(args.length>3){integer("winMultiplier",Math.max(1,Integer.parseInt(args[2])));integer("winMultiTimer",Math.max(0,Integer.parseInt(args[3])));if(args.length>4)integer("winGoal",Math.max(0,Integer.parseInt(args[4])));}return true;}if(!arenaReady||Bukkit.getOnlinePlayers().isEmpty())throw new IllegalStateException("Aucun joueur dans la mine.");
 switch(action){case "diamonds-add":integer("totalDiamonds",integer("totalDiamonds")+value*integer("diamondMultiplier"));call("checkWin",new Class<?>[]{});break;case "diamonds-remove":integer("totalDiamonds",Math.max(0,integer("totalDiamonds")-value));break;case "double-diamonds":integer("diamondMultiplier",2);integer("diamondMultiTimer",Math.min(600,value));break;case "normal-diamonds":integer("diamondMultiplier",1);integer("diamondMultiTimer",0);break;case "clear-mobs":for(Entity e:Bukkit.getWorlds().get(0).getEntities())if(e instanceof Monster)e.remove();break;default:for(Player p:Bukkit.getOnlinePlayers()){switch(action){case "diamant1":call("spawnDiamonds",new Class<?>[]{Player.class,int.class,int.class},p,2,60);break;case "diamant2":call("spawnDiamonds",new Class<?>[]{Player.class,int.class,int.class},p,3,200);break;case "tnt1":case "tnt2":case "nuclear":if(action.equals("nuclear"))call("spawnLava",new Class<?>[]{Player.class},p);for(int i=0;i<(action.equals("tnt1")?15:100);i++)call("spawnTNT",new Class<?>[]{Location.class},p.getLocation());break;case "zombie":case "skeleton":Entity e=p.getWorld().spawnEntity(p.getLocation(),action.equals("zombie")?EntityType.ZOMBIE:EntityType.SKELETON);e.setCustomName(viewer);e.setCustomNameVisible(true);break;case "lava":call("spawnLava",new Class<?>[]{Player.class},p);break;case "prison":call("spawnPrison",new Class<?>[]{Player.class,int.class},p,Math.min(300,value));break;case "noprison":call("handleNoPrison",new Class<?>[]{String.class,int.class},p.getName(),Math.min(300,value));break;case "heal":p.setHealth(p.getMaxHealth());break;default:throw new IllegalArgumentException("Interaction inconnue");}}}
 call("updateOverlays",new Class<?>[]{});getLogger().info("SHENPULSE_DIAMOND_COMMAND ok="+action);
 }catch(Exception e){sender.sendMessage("Interaction Diamond Rush refusée : "+e.getMessage());}return true;}
}
